package Q5;
import javax.swing.*;import java.awt.*;import java.awt.event.*;
public class Converter extends JFrame{private final JTextField amount=new JTextField(10);private final JComboBox<String>target=new JComboBox<>(new String[]{"USD","EUR"});private final JLabel result=new JLabel(" ");private static double rate(String c){return c.equals("USD")?0.012:0.011;}public Converter(){super("Currency Converter");setLayout(new FlowLayout());JButton b=new JButton("Convert");add(new JLabel("INR"));add(amount);add(target);add(b);add(result);ActionListener action=e->convert();b.addActionListener(action);amount.addActionListener(action);setDefaultCloseOperation(EXIT_ON_CLOSE);pack();setLocationRelativeTo(null);}private void convert(){try{double a=Double.parseDouble(amount.getText().trim());if(!Double.isFinite(a)||a<0)throw new NumberFormatException();String s=String.format(java.util.Locale.US,"%.2f %s",a*rate((String)target.getSelectedItem()),target.getSelectedItem());result.setText(s);JOptionPane.showMessageDialog(this,s,"Converted",JOptionPane.INFORMATION_MESSAGE);}catch(NumberFormatException e){result.setText("Invalid amount");JOptionPane.showMessageDialog(this,"Invalid amount","Input error",JOptionPane.ERROR_MESSAGE);}}public static void main(String[]x){SwingUtilities.invokeLater(()->new Converter().setVisible(true));}}
